import zlib from 'zlib';
import path from 'path';

const base = 'C:/Users/Administrator/.dsh/sessions/--C-Users-Administrator-Documents-deepseek-harness-default-workspace--';
const ids = [
  'da6775d6-7969-4a7a-b3ee-d60fce610ed4',
