  'fefd17da-d55a-47e5-a0b4-4535210dfe21',
  '5b8643ac-b2ea-4112-a9e5-a964e05ee32f',
  '9497b319-9065-455c-ba04-a5b8f95a74d3',
];

function zstdAll(buf) {
  const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
  const idxs = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idxs.push(i);
  if (idxs.length <= 1) return zlib.zstdDecompressSync(buf).toString('utf8');
  let out = '';
  for (let k = 0; k < idxs.length; k++) {
    const s = idxs[k];
    const e = k + 1 < idxs.length ? idxs[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {}
  }
  return out;
}

const modelRe = /model_used\s*[:=]\s*"([^"]+)"/g;
const pairRe = /"tool"\s*:\s*"([^"]+)"[^\n]{0,240}?"model(?:_used)?"\s*:\s*"([^"]+)"/g;

for (const id of ids) {
  const fp = path.join(base, 'session-' + id, 'session.v4.jsonl.zstd');
  const text = zstdAll(fs.readFileSync(fp));
  const models = {};
  let m;
  modelRe.lastIndex = 0;
  while ((m = modelRe.exec(text))) models[m[1]] = (models[m[1]] || 0) + 1;
  const pairs = {};
  pairRe.lastIndex = 0;
  while ((m = pairRe.exec(text))) {
    const k = m[1] + ' -> ' + m[2];
    pairs[k] = (pairs[k] || 0) + 1;
  }
  console.log('\n==', id.slice(0, 8));
  console.log('models', JSON.stringify(models));
  console.log('pairs', JSON.stringify(pairs));
  console.log('model_used count hint', (text.match(/model_used/g) || []).length);
}

