import fs from 'fs';
import path from 'path';

const dir = path.join(process.env.USERPROFILE, '.dsh/storages/session_projcache/sessions');
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.json'));
const rows = [];
for (const f of files) {
  const full = path.join(dir, f);
  const st = fs.statSync(full);
  if (Date.now() - st.mtimeMs > 36 * 3600 * 1000) continue;
  const j = JSON.parse(fs.readFileSync(full, 'utf8'));
  const r = j.record?.rows || {};
  const g = (x) => (x && x.val !== undefined ? x.val : x);
  const title = g(r.title);
  const model = g(r.modelSelection)?.lastUsed || {};
  const tu = g(r.tokenUsage)?.totals || {};
  const ss = g(r.sessionStats) || {};
  const t = typeof title === 'string' ? title : (title?.text || JSON.stringify(title) || '');
  rows.push({
    mtime: st.mtimeMs,
    sid: f.slice(8, 16),
    title: String(t).replace(/\s+/g, ' ').slice(0, 40),
    model: (model.provider ? model.provider + '/' : '') + (model.model || '?'),
    turns: ss.turns, steps: ss.steps,
    uncached: tu.uncachedInputTokens || 0,
    cache: tu.cacheReadTokens || 0,
    out: tu.outputTokens || 0,
  });
}
rows.sort((a, b) => b.mtime - a.mtime);
for (const x of rows.slice(0, 15)) {
  const hit = x.cache + x.uncached ? Math.round(100 * x.cache / (x.cache + x.uncached)) : 0;
  console.log([x.sid, x.model, 't'+x.turns, 's'+x.steps, 'hit'+hit+'%', 'unc'+x.uncached, 'out'+x.out, x.title].join(' | '));
}
